// Get attempt count from previous execution or start at 1 (coerce to number)
const attemptCount = Number($json.attemptCount) || 1;

// Progressive wait times in minutes (tune as needed)
const waitTimes = [0.5, 1, 2, 3, 5, 5];

// Configurable maximum attempts (matches waitTimes length by default)
const maxAttempts = 6;

// Determine if we've reached or exceeded max attempts
const giveUp = attemptCount >= maxAttempts;

// Calculate wait time for THIS attempt (if giving up, no wait)
const waitMinutes = giveUp ? 0 : waitTimes[Math.min(attemptCount - 1, waitTimes.length - 1)];

// Build output JSON for downstream nodes
return {
  json: {
    waitMinutes,                    // used by Wait node
    attemptCount: attemptCount + 1, // increment for next iteration
    maxAttempts,
    giveUp,
    // include previous data for continuity
    ...$json
  }
};

